// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.diimport android.content.Context/** * NOUS — Marker interface for app initializers contributed via Hilt multibinding. * * Lives in `:core:di` so any feature module can contribute an initializer * without depending on `:app` (which would create a circular dependency). * * Each feature module can contribute an [AppInitializer] to perform boot-time * setup (e.g., warming up a database, registering a skill, subscribing to a * system broadcast, scheduling periodic WorkManager jobs). * * Initializers are run by `AppInitializers` (in `:app`) in [Priority] order. * Initializers with [isBlocking] = true run synchronously on the main thread * during `NousApplication.onCreate`. Initializers with [isBlocking] = false * run on a background thread. * * Critical initializers (Priority.CRITICAL) MUST be blocking and MUST succeed — * their failure halts the app boot. * * Example: * ```kotlin * @Singleton * class DatabaseInitializer @Inject constructor( *     private val database: NousDatabase, * ) : AppInitializer { *     override val priority = Priority.HIGH *     override val isBlocking = true *     override fun initialize(context: Context) { *         database.open() *     } * } * * @Module @InstallIn(SingletonComponent::class) * abstract class DatabaseInitializerModule { *     @Binds @IntoSet *     abstract fun bindDatabaseInitializer(impl: DatabaseInitializer): AppInitializer * } * ``` */interface AppInitializer {    /** When this initializer runs, relative to others. See [Priority]. */    val priority: Priority    /**     * Whether this initializer blocks app boot. Critical/High initializers     * should be blocking; Normal/Lazy should not.     */    val isBlocking: Boolean    /** Perform initialization. Must be idempotent — may be called more than once. */    fun initialize(context: Context)}